    {
      "label": "Ask about the rent",
      "description": "Pergunte quanto custa o aluguel por mês."
    },
    {
      "label": "Ask what's included",
      "description": "Pergunte se o aluguel inclui aquecimento e água."
    },
    {
      "label": "Book a viewing",
      "description": "Sugira um horário para visitar o apartamento e combine o dia e a hora."
    }
  ],
  "openingLine": "Hi, this is Emma at Lakeview. How can I help?",
  "hints": [
    "How much is the rent each month?",
    "Does the rent include heat and water?",
    "Can I see it on Wednesday at 5 p.m.?",
    "Can I come on Tuesday at 4 p.m.?"
  ]
}

