    },
    {
      "label": "Ask about the spray",
      "description": "Pergunte como e com que frequência usar o spray salino."
    }
  ],
  "openingLine": "Hi, this is Emma, a nurse at Lakeview Family Clinic. How can I help?",
  "hints": [
    "I've had a sore throat and a runny nose for two days.",
    "Could I come in Tuesday at 10 a.m.?",
    "How many times a day should I use the saline spray?"
  ]
